/*
 * A276790  Trajectory of 0 under repeated applications of the map psi: 0 ->
 *          0121, 1 -> 0121121, 2 -> 012121.
 * https://oeis.org/A276790
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the n-th symbol (0,1,2) in the infinite word generated by
 *            the morphism 0 → 0 1 2 1 1 → 0 1 2 1 1 2 1 2 → 0 1 2 1 2 1
 *            starting from the word "0"
 * Range:     u8 n <= 99, u16 n <= 99, u32 n <= 99, u64 n <= 99, u128 n <= 99,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

static const seq_t map0[4] = {0, 1, 2, 1};
static const seq_t map1[7] = {0, 1, 2, 1, 1, 2, 1};
static const seq_t map2[6] = {0, 1, 2, 1, 2, 1};

static seq_t *cache = NULL;      /* cached word */
static idx_t  cache_len = 0;     /* length of cached word */

seq_t a(idx_t n)
{
    /* initialise cache if first call */
    if (cache == NULL) {
        cache = (seq_t *)malloc(4 * sizeof(seq_t)); /* initial capacity 4 is enough */
        cache[0] = 0;          /* start word "0" */
        cache_len = 1;
    }

    /* expand until we have at least n+1 symbols */
    while (cache_len <= n) {
        /* compute length of next expansion */
        idx_t new_len = 0;
        for (idx_t i = 0; i < cache_len; ++i) {
            seq_t c = cache[i];
            if (c == 0)          new_len += 4;
            else if (c == 1)     new_len += 7;
            else                 new_len += 6;       /* c == 2 */
        }

        /* allocate new buffer */
        seq_t *new_cache = (seq_t *)malloc(new_len * sizeof(seq_t));
        if (!new_cache) return 0; /* fallback (should not happen) */

        /* fill new buffer */
        idx_t pos = 0;
        for (idx_t i = 0; i < cache_len; ++i) {
            seq_t c = cache[i];
            if (c == 0) {
                new_cache[pos++] = map0[0];
                new_cache[pos++] = map0[1];
                new_cache[pos++] = map0[2];
                new_cache[pos++] = map0[3];
            } else if (c == 1) {
                for (idx_t k = 0; k < 7; ++k) new_cache[pos++] = map1[k];
            } else { /* c == 2 */
                for (idx_t k = 0; k < 6; ++k) new_cache[pos++] = map2[k];
            }
        }

        free(cache);
        cache = new_cache;
        cache_len = new_len;
    }

    return cache[n];
}
